{"command": "cat > /prediction.json << 'EOF'
{
    "vllm/v1/worker/gpu/sampler.py": {
        "_gumbel_sample_kernel": "@triton.jit\ndef _gumbel_sample_kernel(\n    local_argmax_ptr,\n    local_argmax_stride,\n    local_max_ptr,\n    local_max_stride,\n    logits_ptr,\n    logits_stride,\n    seeds_ptr,\n    pos_ptr,\n    is_greedy_ptr,\n    vocab_size,\n    BLOCK_SIZE: tl.constexpr,\n):\n    \"\"\"\n    Optimized Gumbel sampling kernel with two-step reduction.\n    \n    This kernel computes per-block local maximum values and argmax indices\n    over fixed-size vocabulary tiles. The global reduction is performed\n    in a post-processing step.\n    \n    Args:\n        local_argmax_ptr: Pointer to local argmax indices buffer\n        local_argmax_stride: Stride for local argmax buffer\n        local_max_ptr: Pointer to local maximum values buffer\n        local_max_stride: Stride for local max buffer\n        logits_ptr: Pointer to logits tensor\n        logits_stride: Stride for logits tensor\n        seeds_ptr: Pointer to seeds tensor\n        pos_ptr: Pointer to position tensor\n        is_greedy_ptr: Pointer to is_greedy tensor\n        vocab_size: Vocabulary size\n        BLOCK_SIZE: Tile size for vocabulary processing\n    \"\"\"\n    # Each thread block processes one tile of the vocabulary for one request\n    req_idx = tl.program_id(0)  # Which request\n    tile_idx = tl.program_id(1)  # Which vocabulary tile\n    \n    # Calculate the start index for this tile\n    tile_start = tile_idx * BLOCK_SIZE\n    block = tile_start + tl.arange(0, BLOCK_SIZE)\n    mask = block < vocab_size\n    \n    # Load request-specific data\n    is_greedy = tl.load(is_greedy_ptr + req_idx)\n    \n    if is_greedy:\n        # Greedy sampling: no gumbel noise\n        logits = tl.load(\n            logits_ptr + req_idx * logits_stride + block,\n            mask=mask,\n            other=float(\"-inf\"),\n        )\n        \n        # Find local max and argmax within this tile\n        local_idx = tl.argmax(logits, axis=0)\n        local_max = tl.max(logits, axis=0)\n        \n        # Convert local index to global index\n        global_idx = tile_start + local_idx\n        \n    else:\n        # Random sampling with gumbel noise\n        seed = tl.load(seeds_ptr + req_idx)\n        pos = tl.load(pos_ptr + req_idx)\n        gumbel_seed = tl.randint(seed, pos)\n        \n        # Load logits\n        logits = tl.load(logits_ptr + req_idx * logits_stride + block, mask=mask)\n        \n        # Generate gumbel noise for this tile\n        r = tl.rand(gumbel_seed, block).to(tl.float64)\n        gumbel_noise = -tl.log(-tl.log(r + 1e-20) + 1e-20)\n        gumbel_noise = gumbel_noise.to(tl.float32)\n        \n        # Apply gumbel noise\n        noisy_logits = tl.where(mask, logits + gumbel_noise, float(\"-inf\"))\n        \n        # Find local max and argmax within this tile\n        local_idx = tl.argmax(noisy_logits, axis=0)\n        local_max = tl.max(noisy_logits, axis=0)\n        \n        # Convert local index to global index\n        global_idx = tile_start + local_idx\n    \n    # Store local results\n    # Each request has multiple tiles, so we need to store per-tile results\n    output_idx = req_idx * local_argmax_stride + tile_idx\n    tl.store(local_argmax_ptr + output_idx, global_idx)\n    tl.store(local_max_ptr + output_idx, local_max)",
        "gumbel_sample": "def gumbel_sample(\n    logits: torch.Tensor,  # [num_reqs, vocab_size]\n    is_greedy: torch.Tensor,  # [num_reqs]\n    seed: torch.Tensor,  # [num_reqs]\n    pos: torch.Tensor,  # [num_reqs]\n) -> torch.Tensor:\n    \"\"\"\n    Gumbel sampling with two-step reduction.\n    \n    This function uses an optimized kernel that computes per-block local\n    maximum values and argmax indices, then performs a global reduction\n    in post-processing.\n    \n    Args:\n        logits: Logits tensor of shape [num_reqs, vocab_size]\n        is_greedy: Boolean tensor indicating greedy sampling\n        seed: Random seed tensor\n        pos: Position tensor\n    \n    Returns:\n        Sampled token indices of shape [num_reqs]\n    \"\"\"\n    num_reqs, vocab_size = logits.shape\n    \n    # Determine number of tiles needed\n    BLOCK_SIZE = 16384  # Same as original implementation\n    num_tiles = (vocab_size + BLOCK_SIZE - 1) // BLOCK_SIZE\n    \n    # Allocate buffers for local results\n    # Shape: [num_reqs, num_tiles]\n    local_argmax = torch.empty(\n        num_reqs,\n        num_tiles,\n        dtype=torch.int64,\n        device=logits.device,\n    )\n    local_max = torch.empty(\n        num_reqs,\n        num_tiles,\n        dtype=torch.float32,\n        device=logits.device,\n    )\n    \n    # Launch kernel with 2D grid: (num_reqs, num_tiles)\n    grid = (num_reqs, num_tiles)\n    _gumbel_sample_kernel[grid](\n        local_argmax,\n        local_argmax.stride(0),\n        local_max,\n        local_max.stride(0),\n        logits,\n        logits.stride(0),\n        seed,\n        pos,\n        is_greedy,\n        vocab_size,\n        BLOCK_SIZE=BLOCK_SIZE,\n        num_warps=8,\n    )\n    \n    # Post-processing: perform global reduction across tiles\n    # For each request, find the tile with maximum value\n    sampled = torch.empty(num_reqs, dtype=torch.int64, device=logits.device)\n    \n    # Simple CPU post-processing\n    # In a production system, this could be another optimized kernel\n    for req_idx in range(num_reqs):\n        # Find the tile with maximum value\n        max_val = float(\"-inf\")\n        max_idx = 0\n        \n        for tile_idx in range(num_tiles):\n            val = local_max[req_idx, tile_idx].item()\n            idx = local_argmax[req_idx, tile_idx].item()\n            \n            if val > max_val:\n                max_val = val\n                max_idx = idx\n        \n        sampled[req_idx] = max_idx\n    \n    return sampled"
    }
}
EOF"}

